parameters.jsCode:
const raw = $input.all().flatMap(i => i.json.list || []);
const rows = raw.map(r => ({
  date: r.Order_Date, quarter: r.Quarter, year: Number(r.Year),
  customer_type: r.Customer_Type, source: r.Source, device: r.Device,
  region: r.Region, product: r.Product_Exposure, promo: r.Promo_Used,
  discount: Number(r.Discount_Rate), revenue: Number(r.Net_Revenue),
  items: Number(r.Items_Count), distinct_products: Number(r.Distinct_Products),
  campaign: r.Campaign_ID, entry: r.Entry_Experience
}));
const sum = (key, field) => {
  const out = {};
  for (const r of rows) out[r[key]] = +((out[r[key]] || 0) + r[field]).toFixed(2);
  return out;
};
return [{ json: {
  data: JSON.stringify(rows),
  row_count: rows.length,
  revenue_by_customer_type: sum('customer_type', 'revenue'),
  revenue_by_quarter: sum('quarter', 'revenue'),
  revenue_by_source: sum('source', 'revenue'),
  revenue_by_region: sum('region', 'revenue'),
  revenue_by_campaign: sum('campaign', 'revenue'),
  revenue_by_product: sum('product', 'revenue'),
}}];
